int buffer[5] = {1, 2, 3, 4, 5};
int sum = 0;

// Start pointer
int *current = buffer;

// End boundary calculation (one past the last element)
const int *limit = buffer + 5;

// Loop control using pointer comparison
while (current < limit) {
    sum += *current;
    current++; // Advance pointer by sizeof(int)
}

